-- Generated by model/lib/sql/generate.mjs. Loads IMPORT Logistics Discounts from cells/IMPORT Logistics Discounts.csv in the folder of input cells. Two rows for one cell add up.
-- @csv cells/IMPORT Logistics Discounts.csv
INSERT INTO "IMPORT Logistics Discounts" SELECT coalesce(k0."Customer", fpabench_error('cells name a member Customer does not have: ' || c."Customer")), coalesce(k1."Material", fpabench_error('cells name a member Material does not have: ' || c."Material")), coalesce(k2."Years", fpabench_error('cells name a member Years does not have: ' || c."Years")), coalesce(k3."Months", fpabench_error('cells name a member Months does not have: ' || c."Months")), sum(c.value::DOUBLE PRECISION)
FROM csv c LEFT JOIN "dim Customer" k0 ON k0.name = c."Customer" LEFT JOIN "dim Material" k1 ON k1.name = c."Material" LEFT JOIN "dim Years" k2 ON k2.name = c."Years" LEFT JOIN "dim Months" k3 ON k3.name = c."Months"
GROUP BY 1, 2, 3, 4
ON CONFLICT ("Customer", "Material", "Years", "Months") DO UPDATE SET v = EXCLUDED.v;
ANALYZE "IMPORT Logistics Discounts";
